const urls = [];
cy.intercept('**/web/index.php/api/v2/**', req => {
  urls.push(req.method + ' ' + req.url);
  req.continue();
});
cy.visit('/web/index.php/auth/login');
cy.get('input[name="username"]', {
  timeout: 60000
}).type('Admin');
cy.get('input[name="password"]').type('admin123');
cy.get('button[type="submit"]').click();
cy.visit('/web/index.php/directory/viewDirectory');
cy.get('.orangehrm-directory-card', {
  timeout: 90000
}).should('have.length.at.least', 1);
cy.wait(3000);
// --- SEARCH: ketik lalu pilih saran ---
urls.length = 0;
cy.get('.oxd-autocomplete-text-input input[placeholder="Type for hints..."]', {
  timeout: 30000
}).clear().type('Ranga', {
  delay: 120
});
cy.get('.oxd-autocomplete-option', {
  timeout: 30000
}).should('have.length.at.least', 1);
cy.wait(1500);
cy.writeFile('probe-real-typing.json', {
  urls: urls.slice()
});
cy.get('.oxd-autocomplete-option').first().click();
cy.wait(1500);
urls.length = 0;
cy.contains('button', 'Search').click();
cy.wait(8000);
cy.writeFile('probe-real-search.json', {
  urls: urls.slice()
});
cy.document().then(doc => {
  cy.writeFile('probe-real-afterSearch.json', {
    value: (doc.querySelector('.oxd-autocomplete-text-input input') || {}).value,
    cards: doc.querySelectorAll('.orangehrm-directory-card').length
  });
});
// --- RESET setelah ada hasil search ---
urls.length = 0;
cy.contains('button', 'Reset').click();
cy.wait(8000);
cy.document().then(doc => {
  cy.writeFile('probe-real-afterReset.json', {
    value: (doc.querySelector('.oxd-autocomplete-text-input input') || {}).value,
    cards: doc.querySelectorAll('.orangehrm-directory-card').length,
    urls: urls.slice()
  });
});
